"""Short-lived E2B network feasibility probe, separate from model execution."""
import json
import shlex
from typing import Any

# Fixed code, not generated by the model. No provider credentials enter the guest.
PROBE = r'''
import json
import socket
import urllib.error
import urllib.request

results = {}
for name, url in [
    ("allowed_wikipedia", "https://en.wikipedia.org/wiki/Boston"),
    ("unlisted_example", "https://example.com/"),
]:
    try:
        # Ignore environment proxies so we test direct sandbox egress.
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        request = urllib.request.Request(url, headers={"User-Agent": "CrescendoNetworkPreflight/0.1"})
        with opener.open(request, timeout=10) as response:
            results[name] = {"reachable": True, "http_status": response.status}
    except urllib.error.HTTPError as exc:
        # Even a 403 proves that an HTTP server was reachable.
        results[name] = {"reachable": True, "http_status": exc.code}
    except (OSError, urllib.error.URLError):
        results[name] = {"reachable": False}

# TCP only: do not request or read metadata, credentials, or backend content.
# E2B's sandbox-local MMDS uses the metadata IP outside filtered egress.
# A successful handshake here does not prove host/cloud IMDS access.
for name, host, port in [
    ("metadata_tcp", "169.254.169.254", 80),
    ("private_tcp", "10.0.0.1", 80),
]:
    try:
        with socket.create_connection((host, port), timeout=5):
            results[name] = {"reachable": True}
    except OSError:
        results[name] = {"reachable": False}
print(json.dumps(results))
'''


def run_preflight(*, sandbox_type: Any = None) -> dict:
    """Create a restricted desktop, probe networking, always attempt cleanup.

    A failed connection is evidence of non-reachability, not proof that a firewall
    caused it. Redirects, DNS rebinding, IPv6, and authenticated live view still
    need separate verification before claiming complete isolation.
    """
    if sandbox_type is None:
        from e2b_desktop import Sandbox

        sandbox_type = Sandbox
    sandbox = sandbox_type.create(
        timeout=120,
        network={
            "deny_out": ["0.0.0.0/0"],
            "allow_out": ["en.wikipedia.org"],
            "allow_public_traffic": False,
        },
    )
    try:
        result = sandbox.commands.run(
            "python3 -c " + shlex.quote(PROBE), timeout=45,
        )
        return json.loads(result.stdout)
    finally:
        sandbox.kill()
